import { onCleanup } from "march"
import { DevicePreview } from "march/ui"

// salla, geri al: kumandadaki "Salla" düğmesi devicemotion olaylarını üretir; uygulama sert bir sarsıntıda son notu siler
export function ShakeToUndo() {
  let $notes = ["Süt al", "HADİ buluşmasına katıl", "Kodu gözden geçir", "Bisikleti tamir et"]
  let last = 0
  const onMotion = (e: DeviceMotionEvent) => {
    const a = Math.abs(e.acceleration?.x ?? 0)
    if (a > 15 && Date.now() - last > 1200 && $notes.length) { last = Date.now(); $notes = $notes.slice(0, -1) }
  }
  window.addEventListener("devicemotion", onMotion)
  onCleanup(() => window.removeEventListener("devicemotion", onMotion))
  return <DevicePreview device="iphone-15" controls time="9:41" fitHeight={500}>
    <div sx={{ flex: "col", gap: 2, p: 4 }}>
      <span sx={{ text: ["2xl", "bold"] }}>Notlar</span>
      {() => $notes.map((n) => <div class="m-card" sx={{ p: 3 }}>{n}</div>)}
      <span sx={{ text: "sm", color: "muted" }}>{() => ($notes.length ? "Sallayınca son not silinir" : "Hepsi silindi")}</span>
    </div>
  </DevicePreview>
}

import { DevicePreview } from "march/ui"

// gerçek hayattan: etkinlik kartları parmakla kaydırılır (touchstart / touchend), iki parmakla büyür (touchmove).
// Sürükle: kaydır · Shift + sürükle ya da kumanda › Hareketler › Aç: iki parmakla yakınlaş
const EVENTS = ["Kadıköy konseri", "Belgrad piknik", "Gece hackathonu", "Sahil koşusu"]

export function SwipeGallery() {
  let $i = 0
  let $zoom = 1
  let startX = 0
  let startD = 0
  const dist = (t: TouchList) => Math.hypot(t[0]!.clientX - t[1]!.clientX, t[0]!.clientY - t[1]!.clientY)
  const start = (e: TouchEvent) => {
    startX = e.touches[0]!.clientX
    startD = e.touches.length === 2 ? dist(e.touches) : 0
  }
  const move = (e: TouchEvent) => {
    e.preventDefault()   // the cards move, the page does not scroll
    if (e.touches.length === 2 && startD) $zoom = Math.max(0.6, Math.min(2.5, dist(e.touches) / startD))
  }
  const end = (e: TouchEvent) => {
    if (e.touches.length) return
    const dx = e.changedTouches[0]!.clientX - startX
    if (!startD && Math.abs(dx) > 40) $i = ($i + (dx < 0 ? 1 : EVENTS.length - 1)) % EVENTS.length
    startD = 0
  }
  return <DevicePreview device="pixel-8" controls fitHeight={500}>
    <div sx={{ flex: "col", gap: 3, p: 4 }} on:touchstart={start} on:touchmove={move} on:touchend={end}>
      <span sx={{ text: ["xl", "bold"] }}>Bu hafta</span>
      <div class="m-card" sx={{ p: 6, text: ["2xl", "bold"] }} style={() => ({ scale: String($zoom) })}>{() => EVENTS[$i]}</div>
      <span sx={{ text: "sm", color: "muted" }}>{() => `${$i + 1} / ${EVENTS.length} · yakınlık ${$zoom.toFixed(1)}x`}</span>
    </div>
  </DevicePreview>
}

import { test, expect, renderTest } from "march/testing"
import { DevicePreviewLab } from "./DevicePreviewLab.tsx"

// DevicePreviewLab'in testleri: kaydedince Testler sekmesinde çalışır
// adı (aria-label) uyan düğmeye basar; kumandanın adları önizlemenin diline göre Türkçe ya da İngilizce
const press = (s: ReturnType<typeof renderTest>, name: RegExp) => (s.all("button").find((b: Element) => name.test(b.getAttribute("aria-label") ?? "")) as HTMLElement | undefined)?.click()

test("içerik cihazların ekranında; label erişilebilir ad olur", () => {
  const s = renderTest(() => <DevicePreviewLab />)
  expect(s.get(".lab-own")?.textContent).toContain("Kendi cihazım")
  expect(s.get(".lab-phone")?.getAttribute("aria-label")).toBe("Sohbet telefonu")
})

test("masaüstü bir tarayıcı penceresi: adres çubuğu, dokunma yok", () => {
  const s = renderTest(() => <DevicePreviewLab />)
  expect(s.get(".lab-desk")?.className).toContain("m-device-desktop")
  expect(s.get(".lab-desk .m-device-address")?.textContent).toBe("hadi.app/etkinlikler")
})

test("kumanda cihazı çevirir ve çevrimdışı olayını atar", () => {
  const s = renderTest(() => <DevicePreviewLab />)
  press(s, /Çevrimdışı ol|Go offline/)
  expect(s.get(".lab-log")?.textContent).toContain("offline")
  press(s, /Yatay çevir|Turn to landscape/)
  expect(s.get(".lab-phone")?.className).toContain("is-landscape")
})
